1→import type { Database } from "../database.js";
import { immediateTransaction } from "../database.js";
import { AppError } from "../errors.js";
import { CHAIN_ID } from "../config.js";
import {
  decryptSeed,
  deriveBip39Seed,
  deriveEthereumKey,
  encryptSeed,
10→  generateProvisioningMnemonic,
  MAX_ADDRESS_INDEX,
  validateProvisioningMnemonic,
  type DerivedEthereumKey,
} from "./crypto.js";

interface SecretRow {
  encrypted_seed: Uint8Array;
}

20→interface AddressRow {
  account_id: string;
  address_index: number;
  address: string;
  derivation_path: string;
  network: "sepolia";
  chain_id: "11155111";
}

export interface DepositAddress {
30→  accountId: string;
  addressIndex: number;
  address: string;
  derivationPath: string;
  network: "sepolia";
  chainId: "11155111";
}

type DeriveFunction = (seed: Uint8Array, index: number) => DerivedEthereumKey;

40→export class WalletService {
  private constructor(
    private readonly db: Database,
    private readonly seed: Uint8Array,
    private readonly derive: DeriveFunction = deriveEthereumKey,
  ) {}

  static provision(
    db: Database,
    encryptionKey: Uint8Array,
50→    importedMnemonic?: string,
    passphrase = "",
    derive: DeriveFunction = deriveEthereumKey,
  ): WalletService {
    let stored = db
      .prepare("SELECT encrypted_seed FROM wallet_secret WHERE singleton_id = 1")
      .get() as unknown as SecretRow | undefined;

    if (!stored) {
      const assignmentCount = db
60→        .prepare("SELECT COUNT(*) AS count FROM deposit_addresses")
        .get() as unknown as { count: number };
      if (assignmentCount.count !== 0) {
        throw new AppError("INTERNAL_ERROR", "La wallet persistida está incompleta.");
      }
      const mnemonic = importedMnemonic
        ? validateProvisioningMnemonic(importedMnemonic)
        : generateProvisioningMnemonic();
      const seed = deriveBip39Seed(mnemonic, passphrase);
      const encrypted = encryptSeed(seed, encryptionKey);
70→      immediateTransaction(db, () => {
        db.prepare(
          "INSERT INTO wallet_secret (singleton_id, encrypted_seed, created_at) VALUES (1, ?, ?)",
        ).run(encrypted, new Date().toISOString());
      });
      stored = db
        .prepare("SELECT encrypted_seed FROM wallet_secret WHERE singleton_id = 1")
        .get() as unknown as SecretRow;
    }

80→    let seed: Uint8Array;
    try {
      seed = decryptSeed(stored.encrypted_seed, encryptionKey);
    } catch {
      throw new AppError("INTERNAL_ERROR", "No se pudo cargar la wallet cifrada.");
    }

    const service = new WalletService(db, seed, derive);
    service.verifyStartupIntegrity();
    return service;
90→  }

  /** Used by account creation while its surrounding BEGIN IMMEDIATE is active. */
  assignWithinTransaction(accountId: string): DepositAddress {
    const current = this.find(accountId);
    if (current) return current;

    const account = this.db.prepare("SELECT 1 AS found FROM accounts WHERE account_id = ?").get(accountId);
    if (!account) {
      throw new AppError("ACCOUNT_NOT_FOUND", "La cuenta no existe.", { accountId });
100→    }

    const maxRow = this.db
      .prepare("SELECT MAX(address_index) AS max_index FROM deposit_addresses")
      .get() as unknown as { max_index: number | null };
    if (maxRow.max_index === MAX_ADDRESS_INDEX) {
      throw new AppError("INTERNAL_ERROR", "Se agotó el espacio de direcciones de depósito.");
    }
    const addressIndex = maxRow.max_index === null ? 0 : maxRow.max_index + 1;
    const derived = this.derive(this.seed, addressIndex);
110→    const assigned: DepositAddress = {
      accountId,
      addressIndex: derived.addressIndex,
      address: derived.address,
      derivationPath: derived.derivationPath,
      network: "sepolia",
      chainId: CHAIN_ID,
    };

    this.db.prepare(`
120→      INSERT INTO deposit_addresses
        (account_id, address_index, address, derivation_path, network, chain_id)
      VALUES (?, ?, ?, ?, 'sepolia', ?)
    `).run(
      assigned.accountId,
      assigned.addressIndex,
      assigned.address,
      assigned.derivationPath,
      assigned.chainId,
    );
130→    this.db.prepare(
      "INSERT INTO domain_events (type, payload, created_at) VALUES (?, ?, ?)",
    ).run(
      "DepositAddressAssigned",
      JSON.stringify({
        accountId: assigned.accountId,
        addressIndex: assigned.addressIndex,
        address: assigned.address,
        chainId: assigned.chainId,
      }),
140→      new Date().toISOString(),
    );
    return assigned;
  }

  getOrAssign(accountId: string): DepositAddress {
    return immediateTransaction(this.db, () => this.assignWithinTransaction(accountId));
  }

  find(accountId: string): DepositAddress | undefined {
150→    const row = this.db.prepare(`
      SELECT account_id, address_index, address, derivation_path, network, chain_id
      FROM deposit_addresses WHERE account_id = ?
    `).get(accountId) as unknown as AddressRow | undefined;
    return row ? mapAddress(row) : undefined;
  }

  /** Internal repository contract for a future monitor; intentionally not an HTTP endpoint. */
  allAssigned(): DepositAddress[] {
    const rows = this.db.prepare(`
160→      SELECT account_id, address_index, address, derivation_path, network, chain_id
      FROM deposit_addresses ORDER BY address_index ASC
    `).all() as unknown as AddressRow[];
    return rows.map(mapAddress);
  }

  private verifyStartupIntegrity(): void {
    const row = this.db.prepare(`
      SELECT account_id, address_index, address, derivation_path, network, chain_id
      FROM deposit_addresses ORDER BY address_index ASC LIMIT 1
170→    `).get() as unknown as AddressRow | undefined;
    if (!row) return;
    const derived = this.derive(this.seed, row.address_index);
    if (derived.address !== row.address || derived.derivationPath !== row.derivation_path) {
      throw new AppError("INTERNAL_ERROR", "Falló la verificación de integridad de la wallet.");
    }
  }
}

function mapAddress(row: AddressRow): DepositAddress {
180→  return {
    accountId: row.account_id,
    addressIndex: row.address_index,
    address: row.address,
    derivationPath: row.derivation_path,
    network: row.network,
    chainId: row.chain_id,
  };
}

